import { BookOpen, FlaskConical, GraduationCap } from 'lucide-react';
import { academicHighlights, education } from '@/data/portfolio';
import { AnimatedSection } from '@/components/ui/AnimatedSection';

export function EducationSection() { return <section id="education" className="section-wrap section-tint"><AnimatedSection><p className="section-kicker">04 / Education</p><div className="section-intro"><h2>Systems thinking, expanded through AI/ML research.</h2><p>University of Washington Bothell · a foundation spanning distributed systems, parallel computing, machine learning, computer vision, and software engineering.</p></div></AnimatedSection><div className="education-grid"><div className="degree-stack">{education.map((item, index) => <article className="degree-card" key={item.degree}><div className="degree-icon">{index === 0 ? <GraduationCap size={21} /> : <BookOpen size={21} />}</div><p className="eyebrow">{index === 0 ? "Master's degree" : "Bachelor's degree"}</p><h3>{item.degree}</h3><div className="degree-meta"><span>{item.date}</span><span>GPA · {item.gpa}</span></div><div className="course-list">{item.courses.map((course) => <span className="tag" key={course}>{course}</span>)}</div></article>)}</div><article className="highlight-card"><FlaskConical size={21} /><p className="eyebrow">Academic highlights</p><h3>Curiosity across systems and intelligence.</h3><ul>{academicHighlights.map((highlight) => <li key={highlight}>{highlight}</li>)}</ul><p className="placeholder-note">Awards, scholarships, publications, Dean’s List terms, conference presentations, and research links: [Add if applicable]</p></article></div></section>; }
